# Reconstruct each demonstrated grid from its explicit scaffold and intersection values.
g1=[[9]*26 for _ in range(23)]
for c in [1,5,9,13,17,21,25]:
    for r in range(23): g1[r][c]=3
for r in [2,6,10,14,18,22]:
    for c in range(26): g1[r][c]=3
vals1=[[1,1,7,7],[1,1,7,7],[8,8,7,7],[8,8,2,2],[0,0,2,2],[0,0,3,3]]
for i,r in enumerate([2,6,10,14,18,22]):
    for c,v in zip([5,9,13,17],vals1[i]): g1[r][c]=v
print('demo1',transform(g1))
